def.body:
header = {name, value}
unshift(header)
@bytesize = @bytesize + (count(header))
seq = (@insert_count = @insert_count + 1)
@entry_seq[header] = seq
@name_seq[name] = seq
cleanup

@entry_seq.clear
@name_seq.clear
(size - 1).downto(0) do |i|
  header = self[i]
  seq = @insert_count - i
  @entry_seq[header] = seq
  @name_seq[header[0]] = seq
end
